package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.database.Database; import com.ultras.bans.model.*; import com.ultras.bans.utility.DurationUtil; import org.bukkit.Bukkit; import org.bukkit.entity.Player; import net.kyori.adventure.text.Component; import java.time.*; import java.util.*; import java.util.concurrent.*;
public final class PunishmentService { private final ULTRASBansPlugin plugin; private final Database db; public PunishmentService(ULTRASBansPlugin p,Database d){plugin=p;db=d;}
 public CompletableFuture<Boolean> apply(UUID uuid,String username,String ip,PunishmentType type,long duration,String reason,Player actor,String source){ if(type==PunishmentType.WARN){duration=0;} long finalDuration=duration; return db.active(uuid,type).thenCompose(active->{ if(active.isPresent()) return CompletableFuture.completedFuture(false); Instant now=Instant.now(); Instant exp=finalDuration>0?now.plusSeconds(finalDuration):null; String op=actor==null?"CONSOLE":actor.getName(); UUID ou=actor==null?null:actor.getUniqueId(); Player online=Bukkit.getPlayer(uuid); String world=online==null?"":online.getWorld().getName(); String loc=online==null?"":online.getLocation().getBlockX()+","+online.getLocation().getBlockY()+","+online.getLocation().getBlockZ(); PunishmentRecord rec=new PunishmentRecord(0,uuid,username,ip,type,finalDuration<=0,finalDuration,now,exp,reason,op,ou,plugin.serverId(),world,loc,source,PunishmentStatus.ACTIVE); return db.insertPunishment(rec).thenApply(id->{ if(online!=null) enforce(online,type,reason,finalDuration); plugin.security().record(type,actor); plugin.discord().punishment(rec); plugin.networkSender().sendPunishment(rec); return true;});}); }
 private void enforce(Player p,PunishmentType t,String reason,long duration){ switch(t){case BAN,IP_BAN -> {String msg="<red>ᴜʟᴛʀᴀs</red> | You have been banned.<br><gray>Reason: "+reason+"</gray><br><gray>Duration: "+DurationUtil.format(duration)+"</gray><br><gray>Discord: "+plugin.getConfig().getString("links.discord")+"</gray>"; p.kick(TextComp(msg));} case MUTE -> {} case KICK -> p.kick(TextComp("<red>ᴜʟᴛʀᴀs</red> | You have been kicked.<br><gray>Reason: "+reason+"</gray>")); case FREEZE -> plugin.freeze().set(p,true); case JAIL -> plugin.jail().set(p,true); default -> {} } }
 private Component TextComp(String s){return com.ultras.bans.utility.Text.c(s);} public CompletableFuture<Boolean> remove(UUID u,PunishmentType t,Player actor){return db.active(u,t).thenCompose(a->{if(a.isEmpty())return CompletableFuture.completedFuture(false); return db.updateStatus(a.get().id(),PunishmentStatus.REMOVED).thenApply(v->{Player p=Bukkit.getPlayer(u);if(p!=null){if(t==PunishmentType.FREEZE)plugin.freeze().set(p,false);if(t==PunishmentType.JAIL)plugin.jail().set(p,false);}return true;});});}
 public void refresh(Player p){for(PunishmentType t:new PunishmentType[]{PunishmentType.BAN,PunishmentType.IP_BAN,PunishmentType.MUTE,PunishmentType.FREEZE,PunishmentType.JAIL}) db.active(p.getUniqueId(),t).thenAccept(a->{if(a.isPresent()){PunishmentRecord r=a.get(); if(r.expiresAt()!=null&&r.expiresAt().isBefore(Instant.now())){db.updateStatus(r.id(),PunishmentStatus.EXPIRED);return;} Bukkit.getScheduler().runTask(plugin,()->{if(t==PunishmentType.BAN||t==PunishmentType.IP_BAN) enforce(p,t,r.reason(),r.durationSeconds()); if(t==PunishmentType.FREEZE)plugin.freeze().set(p,true); if(t==PunishmentType.JAIL)plugin.jail().set(p,true);});}}); }
 public static long parseDuration(String s){return DurationUtil.parse(s);} }
